//! Raw FFI to the SIDOU C core (`core/sid`), the benchmark workload (`bench/workload.h`) and
//! the portable app logic (`app/`), generated by bindgen. Header-only `static inline` functions are reachable through
//! generated extern wrappers. [`workload`] serialises access to the workload's global state.

mod bindings {
    #![allow(
        non_upper_case_globals,
        non_camel_case_types,
        non_snake_case,
        dead_code,
        unused_qualifications,
        clippy::all
    )]
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use bindings::*;

/// Field offsets and sizes of the core's and the app's structs as the pi32v2 firmware lays
/// them out (ILP32), for reading them from an emulated device's RAM: `ilp32::sid::fc`,
/// `ilp32::sid::SIZE`. The host's layout differs wherever a struct holds a pointer.
pub mod ilp32 {
    #![allow(non_snake_case, non_upper_case_globals, dead_code)]
    include!(concat!(env!("OUT_DIR"), "/ilp32.rs"));
}

pub mod workload;
